V = "ABCDEFG"
E = [("A","B"),("A","C"),("B","C"),("B","D"),("C","D"),
     ("D","E"),("E","F"),("E","G"),("F","G")]

def bilesen_sayisi(dugumler, kenarlar):
    kalan = set(dugumler)
    komsu = {v: set() for v in dugumler}
    for u, v in kenarlar:
        if u in komsu and v in komsu:
            komsu[u].add(v); komsu[v].add(u)
    k = 0
    while kalan:
        yigin = [kalan.pop()]; k += 1
        while yigin:
            x = yigin.pop()
            for y in komsu[x]:
                if y in kalan:
                    kalan.discard(y); yigin.append(y)
    return k

