from itertools import combinations

V = "ABCDEFG"
E = [("A","B"),("A","C"),("B","C"),("B","D"),("C","D"),
     ("D","E"),("E","F"),("E","G"),("F","G")]

def baglantili(kenarlar):
    komsu = {v: set() for v in V}
    for u, v in kenarlar:
        komsu[u].add(v); komsu[v].add(u)
    gorulen = {"A"}; yigin = ["A"]
    while yigin:
        x = yigin.pop()
        for y in komsu[x]:
            if y not in gorulen:
                gorulen.add(y); yigin.append(y)
    return len(gorulen) == len(V)

n = len(V)
