def pruferden_agac(s):
    n = len(s) + 2
    derece = [1] * (n + 1)
    for x in s:
        derece[x] += 1
    kenarlar = []
    for x in list(s):
        for v in range(1, n + 1):
            if derece[v] == 1:
                kenarlar.append((v, x))
                derece[v] -= 1; derece[x] -= 1
                break
    kalan = [v for v in range(1, n + 1) if derece[v] == 1]
    kenarlar.append((kalan[0], kalan[1]))
    return kenarlar

