def uzakliklar(s):
    d = {s: 0}; kuyruk = [s]
    while kuyruk:
        x = kuyruk.pop(0)
        for y in komsu[x]:
            if y not in d:
                d[y] = d[x] + 1; kuyruk.append(y)
    return d

