from itertools import combinations

V = "ABCDEFG"
E = [("A","B"),("A","C"),("B","C"),("B","D"),("C","D"),
     ("D","E"),("E","F"),("E","G"),("F","G")]
kenar = {tuple(sorted(e)) for e in E}

def bagimsiz(S):
    return all(tuple(sorted((a, b))) not in kenar for a, b in combinations(S, 2))

def klik(S):
    return all(tuple(sorted((a, b))) in kenar for a, b in combinations(S, 2))

def orter(S):
    s = set(S)
    return all(a in s or b in s for a, b in kenar)

def en_buyuk(kosul):
    for k in range(len(V), 0, -1):
        for S in combinations(V, k):
            if kosul(S):
                return k, S
    return 0, ()

def en_kucuk(kosul):
    for k in range(0, len(V) + 1):
        for S in combinations(V, k):
            if kosul(S):
                return k, S
    return len(V), tuple(V)

a, As = en_buyuk(bagimsiz)
w, Ws = en_buyuk(klik)
b, Bs = en_kucuk(orter)
print("alpha =", a, As)
print("omega =", w, Ws)
print("beta  =", b, Bs)
print("Gallai: alpha + beta =", a + b, "| n =", len(V))
tumleyen = {e for e in combinations(V, 2) if e not in kenar}
print("tumleyen kenar sayisi:", len(tumleyen))
print("A,D,F tumleyende klik mi:",
      all(tuple(sorted((a, b))) in tumleyen for a, b in combinations(As, 2)))

def turan(n, r):
    boy = [n // r + (1 if i < n % r else 0) for i in range(r)]
    return boy, sum(boy[i] * boy[j] for i in range(r) for j in range(i + 1, r))
