V = "ABCDEFG"
G = [("A","B"),("A","C"),("B","C"),("B","D"),("C","D"),
     ("D","E"),("E","F"),("E","G"),("F","G")]
GP = G + [("A","D"),("C","E"),("D","F")]

def P(dugumler, kenarlar, k):
    kenarlar = sorted({tuple(sorted(e)) for e in kenarlar})
    if not kenarlar:
        return k ** len(dugumler)
    u, v = kenarlar[0]
    silme = [e for e in kenarlar if e != (u, v)]
    esle = {x: (u if x == v else x) for x in dugumler}
    yeni_d = sorted({esle[x] for x in dugumler})
    yeni_k = {tuple(sorted((esle[a], esle[b]))) for a, b in silme if esle[a] != esle[b]}
    return P(dugumler, silme, k) - P(yeni_d, sorted(yeni_k), k)

def acgozlu(dugumler, kenarlar, sira):
    komsu = {x: set() for x in dugumler}
    for a, b in kenarlar:
        komsu[a].add(b); komsu[b].add(a)
    renk = {}
    for x in sira:
        kullanilan = {renk[y] for y in komsu[x] if y in renk}
        c = 1
        while c in kullanilan:
            c += 1
        renk[x] = c
    return renk

for ad, E in [("G ", G), ("G+", GP)]:
    d = {x: sum(1 for a, b in E if x in (a, b)) for x in V}
    print(ad, "Delta =", max(d.values()), "| P(.,2) =", P(list(V), E, 2),
          "| P(.,3) =", P(list(V), E, 3), "| P(.,4) =", P(list(V), E, 4))
    chi = next(k for k in range(1, 8) if P(list(V), E, k) > 0)
    print("   kromatik sayi:", chi, "| acgozlu (A..G sirasi) renk sayisi:",
          max(acgozlu(list(V), E, list(V)).values()))

print("renklendirme G (A..G):", acgozlu(list(V), G, list(V)))
print("renklendirme G+ (A..G):", acgozlu(list(V), GP, list(V)))

