     ("D","E"),("E","F"),("E","G"),("F","G")]

def kenar_boya(E, k):
    kullanilan = {v: set() for v in V}
    renk = [0] * len(E)
    def rec(i):
        if i == len(E):
            return True
        u, v = E[i]
        for c in range(1, k + 1):
            if c not in kullanilan[u] and c not in kullanilan[v]:
                kullanilan[u].add(c); kullanilan[v].add(c); renk[i] = c
                if rec(i + 1):
                    return True
                kullanilan[u].discard(c); kullanilan[v].discard(c); renk[i] = 0
        return False
    return (renk if rec(0) else None)

